package com.learningspace;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;
public class MainActivity extends Activity {
 public static final String ORIGIN="https://learning-space-shraj.balmydream64.chatgpt.site";private WebView web;private ValueCallback<Uri[]> fileCallback;private final Handler handler=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xfff8faf3);getWindow().setNavigationBarColor(0xfff8faf3);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xfff8faf3);LinearLayout toolbar=new LinearLayout(this);toolbar.setPadding(14,8,14,8);Button dashboard=new Button(this);dashboard.setText("Learning Space");dashboard.setOnClickListener(v->web.loadUrl(ORIGIN));Button widgets=new Button(this);widgets.setText("Widgets");widgets.setOnClickListener(v->showWidgets());Button browser=new Button(this);browser.setText("Browser");browser.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(ORIGIN+safePath(getIntent().getStringExtra("path"))))));toolbar.addView(dashboard,new LinearLayout.LayoutParams(0,(int)(48*getResources().getDisplayMetrics().density),1));toolbar.addView(widgets);toolbar.addView(browser);root.addView(toolbar);TextView syncHint=new TextView(this);syncHint.setText("If sign-in opens in your browser, share a widget snapshot from Settings.");syncHint.setTextColor(0xff718965);syncHint.setTextSize(11);syncHint.setPadding(16,2,16,8);root.addView(syncHint);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Bridge(),"LearningSpaceNative");
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri u=request.getUrl();if(allowed(u))return false;if("https".equals(u.getScheme())){startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}return true;}@Override public void onPageFinished(WebView view,String url){if(allowed(Uri.parse(url)))view.evaluateJavascript("window.dispatchEvent(new Event('learning-native-ready'))",null);}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.setType("*/*");pick.addCategory(Intent.CATEGORY_OPENABLE);pick.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","application/epub+zip","application/json"});try{startActivityForResult(pick,21);return true;}catch(Exception e){fileCallback=null;return false;}}});
  if(!importIntent(getIntent()))web.loadUrl(ORIGIN+safePath(getIntent().getStringExtra("path")));
 }
 static String safePath(String path){return path!=null&&(path.matches("\\?page=(today|library|activity|settings)")||path.matches("\\?resource=[a-zA-Z0-9_-]{1,100}"))?path:"";}
 static boolean allowed(Uri u){return "https".equals(u.getScheme())&&Uri.parse(ORIGIN).getHost().equals(u.getHost());}
 class Bridge {@JavascriptInterface public void updateWidgets(String json){handler.post(()->{if(web.getUrl()==null||!allowed(Uri.parse(web.getUrl())))return;try{WidgetStore.save(MainActivity.this,json);LearningWidget.updateAll(MainActivity.this);}catch(Exception ignored){}});}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==21&&fileCallback!=null){fileCallback.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);fileCallback=null;}if(req==22&&result==RESULT_OK&&data!=null)importUri(data.getData());}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(!importIntent(intent))web.loadUrl(ORIGIN+safePath(intent.getStringExtra("path")));}
 private boolean importIntent(Intent intent){Uri u=null;if(Intent.ACTION_SEND.equals(intent.getAction()))u=intent.getParcelableExtra(Intent.EXTRA_STREAM);else if(Intent.ACTION_VIEW.equals(intent.getAction())&&intent.getData()!=null&&"content".equals(intent.getData().getScheme()))u=intent.getData();if(u!=null){importUri(u);web.loadUrl(ORIGIN);return true;}return false;}
 private void importUri(Uri uri){try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0){bytes.write(b,0,n);if(bytes.size()>50000)throw new IOException("Snapshot too large");}WidgetStore.save(this,bytes.toString("UTF-8"));LearningWidget.updateAll(this);new AlertDialog.Builder(this).setTitle("Widgets updated").setMessage("Your local widget snapshot is ready. Widgets show the last synchronized plan. Open the dashboard to refresh it.").setPositiveButton("OK",null).show();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Could not import snapshot").setMessage("Choose the widget snapshot exported from Settings → Android & widgets. Course imports and full backups use a different format.").setPositiveButton("OK",null).show();}}
 private void showWidgets(){String[] options={"Today’s plan · 4×2","Streak · 2×2","Daily goal · 2×1","Next lesson · 4×1","Reading · 2×2","Weekly rhythm · 4×2","Import widget snapshot","Refresh cached widgets"};new AlertDialog.Builder(this).setTitle("Your learning, at a glance").setItems(options,(dialog,which)->{if(which<6){Class<?>[] classes={TodayWidget.class,StreakWidget.class,GoalWidget.class,NextWidget.class,ReadingWidget.class,WeekWidget.class};android.appwidget.AppWidgetManager manager=android.appwidget.AppWidgetManager.getInstance(this);if(Build.VERSION.SDK_INT>=26&&manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(this,classes[which]),null,null);else Toast.makeText(this,"Long press your home screen → Widgets → Learning Space",Toast.LENGTH_LONG).show();}else if(which==6){Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.setType("application/json");pick.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(pick,22);}else LearningWidget.updateAll(this);}).setNeutralButton("How to sync",(d,w)->new AlertDialog.Builder(this).setMessage("The dashboard sends a widget snapshot when you use it inside this app. If sign-in opens in your browser, use Settings → Android & widgets → Share widget snapshot, then choose Learning Space. Widgets are cached, not a background account sync.").setPositiveButton("OK",null).show()).show();}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(fileCallback!=null)fileCallback.onReceiveValue(null);web.removeJavascriptInterface("LearningSpaceNative");web.destroy();super.onDestroy();}
}
